<?php
require __DIR__.'/includes/bootstrap.php';require_admin();require __DIR__.'/includes/layout.php';
$allowed=['Pending','Approved','Rejected','Completed','Cancelled'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
 if($action==='status'){$id=(int)($_POST['id']??0);$status=post_string('status',20);$q=$pdo->prepare('SELECT status FROM appointments WHERE id=?');$q->execute([$id]);$current=$q->fetchColumn();$transitions=['Pending'=>['Approved','Rejected','Cancelled'],'Approved'=>['Completed','Cancelled'],'Rejected'=>[],'Completed'=>[],'Cancelled'=>[]];if(!$current||!in_array($status,$transitions[$current]??[],true))flash('error','That appointment status change is not allowed.');else{$pdo->prepare('UPDATE appointments SET status=? WHERE id=?')->execute([$status,$id]);audit($pdo,'appointment.status_'.$status,'appointment',$id);flash('success','Appointment marked '.$status.'.');}redirect('appointments.php');}
 if($action==='create'){$patient=(int)($_POST['patient_id']??0);$dentist=(int)($_POST['dentist_id']??0);$service=(int)($_POST['service_id']??0);$date=post_string('appointment_date',10);$start=post_string('start_time',5);$notes=post_string('notes',2000);$errors=[];$q=$pdo->prepare('SELECT * FROM dental_services WHERE id=? AND is_active=1');$q->execute([$service]);$svc=$q->fetch();if(!$patient||!$dentist||!$svc||!valid_date($date)||!valid_time($start))$errors[]='Select a valid patient, dentist, service, date and time.';if(!$errors){$end=(new DateTime($date.' '.$start))->modify('+'.(int)$svc['duration_minutes'].' minutes')->format('H:i:s');$dow=(int)(new DateTime($date))->format('w');$q=$pdo->prepare('SELECT COUNT(*) FROM dentist_schedules WHERE dentist_id=? AND day_of_week=? AND is_active=1 AND start_time<=? AND end_time>=?');$q->execute([$dentist,$dow,$start,$end]);if(!$q->fetchColumn())$errors[]='The selected time is outside this dentist’s available schedule.';$q=$pdo->prepare("SELECT COUNT(*) FROM unavailable_slots WHERE (dentist_id=? OR dentist_id IS NULL) AND unavailable_date=? AND (start_time IS NULL OR (start_time<? AND end_time>?))");$q->execute([$dentist,$date,$end,$start]);if($q->fetchColumn())$errors[]='The selected time is blocked or unavailable.';$q=$pdo->prepare("SELECT COUNT(*) FROM appointments WHERE dentist_id=? AND appointment_date=? AND status IN ('Pending','Approved') AND start_time<? AND end_time>?");$q->execute([$dentist,$date,$end,$start]);if($q->fetchColumn())$errors[]='That dentist already has an overlapping appointment.';}
 if(!$errors){$q=$pdo->prepare('INSERT INTO appointments(patient_id,dentist_id,service_id,appointment_date,start_time,end_time,status,notes,service_name_snapshot,service_price_snapshot) VALUES(?,?,?,?,?,?,\'Pending\',?,?,?)');$q->execute([$patient,$dentist,$service,$date,$start,$end,$notes?:null,$svc['name'],$svc['price']]);$id=(int)$pdo->lastInsertId();audit($pdo,'appointment.created','appointment',$id);flash('success','Appointment request created.');redirect('appointments.php');}}
}
$where=[];$params=[];foreach(['status'=>'a.status','date'=>'a.appointment_date','dentist'=>'a.dentist_id'] as $k=>$col){if(!empty($_GET[$k])){$where[]="$col=?";$params[]=$_GET[$k];}}if(!empty($_GET['q'])){$where[]="CONCAT(p.first_name,' ',p.last_name) LIKE ?";$params[]='%'.trim($_GET['q']).'%';}$sql="SELECT a.*,CONCAT(p.first_name,' ',p.last_name) patient,CONCAT(d.first_name,' ',d.last_name) dentist FROM appointments a JOIN patients p ON p.id=a.patient_id JOIN dentists d ON d.id=a.dentist_id".($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY a.appointment_date DESC,a.start_time DESC';$q=$pdo->prepare($sql);$q->execute($params);$appointments=$q->fetchAll();$patients=$pdo->query("SELECT id,CONCAT(first_name,' ',last_name) name FROM patients ORDER BY last_name")->fetchAll();$dentists=$pdo->query("SELECT id,CONCAT(first_name,' ',last_name) name FROM dentists WHERE is_active=1 ORDER BY last_name")->fetchAll();$services=$pdo->query('SELECT id,name,price FROM dental_services WHERE is_active=1 ORDER BY name')->fetchAll();page_header('Appointment Management','appointments');
?><?php if(!empty($errors)):?><div class="alert error"><?=e(implode(' ',$errors))?></div><?php endif?><section class="card"><div class="toolbar"><h2>All appointments</h2><form class="filters"><input name="q" placeholder="Patient name" value="<?=e($_GET['q']??'')?>"><input type="date" name="date" value="<?=e($_GET['date']??'')?>"><select name="status"><option value="">All statuses</option><?php foreach($allowed as $s):?><option <?=$s===($_GET['status']??'')?'selected':''?>><?=$s?></option><?php endforeach?></select><select name="dentist"><option value="">All dentists</option><?php foreach($dentists as $d):?><option value="<?=$d['id']?>" <?=((string)$d['id']===($_GET['dentist']??''))?'selected':''?>>Dr. <?=e($d['name'])?></option><?php endforeach?></select><button>Filter</button></form></div><div class="table-wrap"><table><thead><tr><th>Patient / Service</th><th>Dentist</th><th>Schedule</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($appointments as $a):?><tr><td><strong><?=e($a['patient'])?></strong><br><small><?=e($a['service_name_snapshot'])?> · ₱<?=number_format((float)$a['service_price_snapshot'],2)?></small></td><td>Dr. <?=e($a['dentist'])?></td><td><?=date('M j, Y',strtotime($a['appointment_date']))?><br><small><?=date('g:i A',strtotime($a['start_time']))?>–<?=date('g:i A',strtotime($a['end_time']))?></small></td><td><?=status_badge($a['status'])?></td><td><form method="post" class="actions"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$a['id']?>"><?php if($a['status']==='Pending'):?><button class="btn sm" name="status" value="Approved">Approve</button><button class="btn danger sm" name="status" value="Rejected">Reject</button><?php elseif($a['status']==='Approved'):?><button class="btn sm" name="status" value="Completed">Complete</button><button class="btn danger sm" name="status" value="Cancelled">Cancel</button><?php else:?><span>—</span><?php endif?></form></td></tr><?php endforeach?><?php if(!$appointments):?><tr><td colspan="5" class="empty">No appointments match these filters.</td></tr><?php endif?></tbody></table></div></section><section class="card" style="margin-top:20px"><h2>Create appointment request</h2><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="create"><label>Patient<select name="patient_id" required><option value="">Select patient</option><?php foreach($patients as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach?></select></label><label>Dentist<select name="dentist_id" required><option value="">Select dentist</option><?php foreach($dentists as $d):?><option value="<?=$d['id']?>">Dr. <?=e($d['name'])?></option><?php endforeach?></select></label><label>Service<select name="service_id" required><option value="">Select service</option><?php foreach($services as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?> — ₱<?=number_format((float)$s['price'],2)?></option><?php endforeach?></select></label><label>Date<input type="date" name="appointment_date" min="<?=date('Y-m-d')?>" required></label><label>Start time<input type="time" name="start_time" required></label><label class="full">Notes<textarea name="notes" rows="3"></textarea></label><div class="full"><button>Create pending request</button></div></form></section><?php page_footer();
